const { test } = require('node:test');
const assert = require('node:assert/strict');
const catalog = require('../locations/catalog.v1.json');
const { LocationSearch } = require('../location-search.js');
const search = new LocationSearch(catalog);

// Generated by running the original C# AutocompleteService at catalog.sourceCommit,
// with its original CSV/ZIP files, rather than by this JavaScript implementation.
for (const { term, ids } of require('./master-location-results.json')) {
    test(`matches master ranking: ${JSON.stringify(term)}`, () => {
        assert.deepEqual(search.search(term).map(result => result.id), ids);
    });
}

test('ZIP results retain city coordinates and leading zeros', () => {
    const beverly = search.search('90210').find(city => city.name === 'Beverly Hills');
    assert.equal(beverly.state, 'CA');
    assert.equal(beverly.type, 'city');
    const source = catalog.cities.find(city => city[0] === beverly.name && city[1] === beverly.state);
    assert.equal(beverly.latitude, source[2]);
    assert.equal(beverly.longitude, source[3]);
    assert(search.search('02108').some(city => city.name === 'Boston'));
});

test('the query cache is bounded and normalized queries reuse results', () => {
    assert.strictEqual(search.search('MIAMI'), search.search(' miami '));
    for (let index = 0; index < 150; index++) search.search(String(10000 + index));
    assert.equal(search.cache.size, 128);
});

test('states and regions have stable IDs and no fabricated coordinates', () => {
    assert.deepEqual(search.search('california')[0], {
        id: 'State:CA:CALIFORNIA', name: 'California', state: 'CA',
        type: 'state', latitude: 0, longitude: 0
    });
    assert.equal(search.search('midwest plains')[0].id, 'Region:MIDWESTPLAINS:MIDWEST-PLAINS');
});
